INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 1, 'theory', 'Quiz: SQL basics');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 1, 0, 'What does the star do in the query SELECT * FROM customers?', '["Selects all columns of the table", "Selects only the first row", "Counts the rows", "Multiplies the column values"]', 0, 'The star replaces the list of columns and means "all columns". Rows are chosen by a condition, and without one all of them are returned.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 1, 1, 'What does 7 / 2 equal in SQLite if both numbers are integers?', '["3.5", "4", "3", "A division error"]', 2, 'Dividing an integer by an integer throws away the fractional part. To get 3.5, write one of the numbers as a fraction: 7 / 2.0.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 1, 2, 'How do you correctly write a string with an apostrophe, O''Brien, in a query?', '["''O\\''Brien''", "\"O''Brien\"", "''O''''Brien''", "''O'' + ''Brien''"]', 2, 'Inside a string in single quotes the apostrophe is doubled. In the SQL standard, double quotes are for names, not for values.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 1, 3, 'What is a foreign key for?', '["To speed up sorting", "To refer to a row of another table", "To forbid empty values", "To encrypt data"]', 1, 'A foreign key stores the value of another table''s primary key. That is how an order is linked to a customer and an item to a product, without copying data.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 1, 4, 'What does DISTINCT do in the query SELECT DISTINCT city, vip FROM customers?', '["Removes repeats in city and in vip separately", "Removes rows where the pair of values matched completely", "Keeps only VIP customers", "Sorts the result by city"]', 1, 'DISTINCT works on the whole result row: rows are considered identical when all the selected columns match.');
